import {MESSAGE_CATALOG,messageCase} from './message-content.mjs';
import {letterState,currentLetter,letterSuggestion,drawLetter,selectLetter,carryLetter,keepLetter,recoverLetters} from './letter-trail-core.mjs';
import {messagePage,bindMessages} from './message-ui.mjs';
import {puppetArt} from './loft-art.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=p=>`#${p}/letters`;
const KINDS=[['detail','One useful detail'],['pair','Two details together'],['reader','This reader’s reason']];
const label=k=>KINDS.find(([id])=>id===k)?.[1]||'One useful detail';
const names={rabbit:'Rabbit',kitten:'Kitten',dragon:'Dragon',pip:'Pip',dot:'Dot'};
const kind=c=>c.kind||'detail';
const currentWork=(e,p)=>e.notebook.cases[e.caseId]?.[p];
const catalogue=c=>({...c,readerName:c.readerName||names[c.actor],readerNeed:c.readerNeed||c.question,readerKnowledge:c.readerKnowledge||'The scene offers clues. The note must tell this reader what matters.'});
function heading(place){return `<header class="msg-heading"><a class="back" href="#${place}"><span aria-hidden="true">←</span> ${place==='post'?'Back to my delivery':'Back to the Story Loft'}</a><h1>${place==='post'?'The changing letter round':'Letters on the little stage'}</h1><p>New readers. New reasons to revise. Your other ${place==='post'?'delivery':'show'} will wait.</p></header>`;}
export function letterEntry(place){return `<aside class="msg-entry"><div><strong>The next letter has a different reader.</strong><p>Help a note do its job, then give the next reader something useful to know.</p><a href="#${place}/messages">Keep exploring the three first notes</a></div><a class="secondary" href="${route(place)}/round">Find a changing letter</a></aside>`;}
function retention(){return '<p class="tiny">This notebook keeps the latest 24 letters, plus letters currently open at either desk. A new draw can replace an older paused letter on this shelf. Download notes in Grown-up notes to keep older writing.</p>';}
function round(state,place){const s=letterState(state),suggestion=letterSuggestion(state),x=currentLetter(state,place);return `${heading(place)}<section class="letter-round"><h2 id="letter-title" tabindex="-1">Who needs a letter today?</h2><div class="letter-next"><div><h3>${esc(label(suggestion.kind))}</h3><p>${esc(suggestion.reason)}</p><p class="tiny">You can choose any kind.</p></div><button type="button" class="primary" data-letter-draw="auto">Find my next letter</button></div>${x?`<p class="letter-paused"><strong>Your open letter:</strong> ${esc(x.case.title)}<button type="button" class="secondary" data-letter-open="${x.episode.id}">Return to this draft</button></p>`:''}<details class="letter-manual" open><summary>Choose any kind of letter</summary><div class="letter-kinds">${KINDS.map(([id,text])=>`<button type="button" class="secondary" data-letter-draw="${id}"><strong>${esc(text)}</strong><span>${id==='detail'?'Name the object, place or action.':id==='pair'?'Connect two useful details or put actions in order.':'Think about what this reader knows, and what they need to know.'}</span></button>`).join('')}</div></details><details class="letter-shelf" ${s.episodes.length?'open':''}><summary>My kept and paused letters (${s.episodes.length})</summary>${s.episodes.length?`<div class="letter-shelf-list">${[...s.episodes].reverse().map(e=>{const c=messageCase(e.caseId),draft=currentWork(e,place);return `<article><div class="letter-shelf-reader">${puppetArt(c.actor)}</div><div><strong>${esc(c.title)}</strong><p>${esc(label(kind(c)))} · ${e.firstKept?'A version was kept':'Paused for now'}${e.priorExposure==='fresh'?'':' · You may have seen this one before'}</p></div>${draft?`<button type="button" class="secondary" data-letter-open="${e.id}">Open letter ${e.id}</button>`:`<button type="button" class="secondary" data-letter-bring="${e.id}">Bring letter ${e.id} here</button>`}</article>`;}).join('')}</div>`:'<p>Your first letter will wait here when you take a break.</p>'}</details><p><a href="#${place}/messages">The three original notes and their drafts</a> · <a href="#notes">Grown-up notes and downloads</a></p><details class="grownup-note"><summary>For grown-ups</summary><p>The suggested letter is about a message’s structure. Choose any kind, with any reading help.</p><p>Twelve authored notes travel around this town. Familiar notes return as rereading; their words are not generated by AI. “You may have seen this one before” marks a familiar note, or one whose earlier exposure is uncertain.</p>${retention()}</details></section>`;}
function keepControls(x){const w=x.work,e=x.episode,eligible=['play','human'].includes(w.page)||w.page==='story'&&w.playback===1;if(!eligible)return '';const human=w.page==='human',selected=x.case.cards.find(c=>c.id===w.cardId);return `<section class="letter-keep" aria-label="Keep a version"><h3>Something to keep?</h3>${!human?`<p><strong>Card to keep:</strong> “${esc(selected?.text||'No card picked yet.')}”</p>`:''}<p>Trying cards is exploring. ${human?'A person reads your own words with you.':'Keep this card if you like it. It helps pick your next letter.'}</p>${e.firstKept?`<p class="letter-kept" role="status">You kept a version of this letter already. Keep playing as long as you like.</p><details class="grownup-note"><summary>For grown-ups</summary><p>Only the first kept version of a letter counts toward a new suggestion. Later revisions and plays are exploring.</p></details>`:`<button type="button" class="primary" data-letter-keep="${human?'human':'supplied'}">${human?'Keep my own message, read together':'Keep this card'}</button>`}${!human&&w.original?'<button type="button" class="secondary" data-msg-action="human">Read and keep my own words instead</button>':''}<button type="button" class="secondary" data-letter-round>Choose the next letter</button></section>`;}
export function letterPage(state,place,detail){const s=letterState(state);if(!s)return `${heading(place)}<section class="panel"><h2 id="letter-title" tabindex="-1">An earlier letter round is kept</h2><p>This format cannot be opened here. It stays exact in notes downloads. You can keep that record while opening a fresh round.</p><button type="button" class="secondary" data-letter-recover>Keep the earlier record and start fresh</button></section>`;const x=currentLetter(state,place);if(!x||detail==='round'||detail==='choose')return round(state,place);const c=catalogue(x.case),e=x.episode;c.cards=e.cardOrder.map(id=>c.cards.find(v=>v.id===id));c.clues=e.clueOrder.map(id=>c.clues.find(v=>v.id===id));return messagePage(x.adapter,place,detail,{case:c,heading:heading(place),roundRoute:route(place)+'/round',banner:`<div class="letter-ticket"><strong>Letter ${e.id}: ${esc(label(kind(c)))}</strong><span>${e.priorExposure==='fresh'?'A new note in this round.':e.priorExposure==='unknown'?'You may have seen this letter before.':'A familiar note in a new round. Revisit what its reader needs.'}</span></div>`,controls:keepControls(x)});}
export function bindLetterTrail(state,place,ctx){const refresh=selector=>{ctx.save();ctx.render();ctx.focus?.(selector||'#msg-title');};const go=(url,selector='#msg-title')=>{if(location.hash===url){ctx.navigate(url);ctx.focus?.(selector);}else{window.addEventListener('hashchange',()=>ctx.focus?.(selector),{once:true});ctx.navigate(url);}};const draw=k=>{if(drawLetter(state,place,k)){ctx.save();go(route(place));}};
 const x=currentLetter(state,place);if(x)bindMessages(x.adapter,place,{...ctx,save:()=>ctx.save(),routeFor:route,onCarry:()=>carryLetter(state,place),onNext:()=>draw('auto')});
 document.querySelectorAll('[data-letter-draw]').forEach(b=>b.onclick=()=>draw(b.dataset.letterDraw));
 document.querySelectorAll('[data-letter-open]').forEach(b=>b.onclick=()=>{if(selectLetter(state,place,Number(b.dataset.letterOpen))){ctx.save();go(route(place));}});
 document.querySelectorAll('[data-letter-bring]').forEach(b=>b.onclick=()=>{if(selectLetter(state,place,Number(b.dataset.letterBring))){ctx.save();go(route(place));}});
 document.querySelectorAll('[data-letter-keep]').forEach(b=>b.onclick=()=>{if(keepLetter(state,place,b.dataset.letterKeep))refresh('.letter-keep');});
 document.querySelectorAll('[data-letter-round]').forEach(b=>b.onclick=()=>go(route(place)+'/round','#letter-title'));
 document.querySelector('[data-letter-recover]')?.addEventListener('click',()=>{if(recoverLetters(state))refresh('#letter-title');});
}
export function letterNotes(state){if(!Object.hasOwn(state,'letterTrail'))return '';const s=letterState(state);return `<details class="panel"><summary>Changing letters: readers and revision</summary><p>Only first-kept supplied versions can inform message-structure suggestions. Card experiments, original writing, narration, together-reading, familiar notes and carried copies are not independent reading/writing evidence. Human-read originals are ungraded. Current drafts and local option orders are preserved. ${MESSAGE_CATALOG.length} authored cases; no runtime AI.</p>${retention()}${s?`<p>Suggested next kind: ${esc(label(s.suggested.kind))}. ${esc(s.suggested.reason)}</p>${s.episodes.map(e=>`<section><h3>Letter ${e.id}: ${esc(messageCase(e.caseId).title)}</h3><pre>${esc(JSON.stringify(e,null,2))}</pre></section>`).join('')}${Object.hasOwn(s,'recovered')?`<h3>Earlier round retained in full</h3><pre>${esc(JSON.stringify(s.recovered,null,2))}</pre>`:''}`:`<p>Unsupported format retained unchanged.</p><pre>${esc(JSON.stringify(state.letterTrail,null,2))}</pre>`}</details>`;}
